-- AccessGrant (transaction): Request -> approval -> provisioning -> revocation of one entitlement for one employee.
CREATE TABLE `access_grant` (
  `grant_id` VARCHAR(40) NOT NULL COMMENT 'Primary key: GRANT-<employee-id>-NNN.',
