  CONSTRAINT `fk_access_grant_access_role_id` FOREIGN KEY (`access_role_id`) REFERENCES `access_role` (`access_role_id`),
  CONSTRAINT `fk_access_grant_onboarding_case_id` FOREIGN KEY (`onboarding_case_id`) REFERENCES `onboarding_case` (`onboarding_case_id`),
  CONSTRAINT `fk_access_grant_offboarding_case_id` FOREIGN KEY (`offboarding_case_id`) REFERENCES `offboarding_case` (`offboarding_case_id`),
  CONSTRAINT `fk_access_grant_approved_by_manager_id` FOREIGN KEY (`approved_by_manager_id`) REFERENCES `manager` (`manager_id`),
  CONSTRAINT `ck_access_grant_request_reason` CHECK (`request_reason` IN ('NEW_HIRE', 'ROLE_CHANGE', 'EXISTING_BASELINE')),
  CONSTRAINT `ck_access_grant_approval_status` CHECK (`approval_status` IN ('PENDING', 'APPROVED', 'REJECTED')),
