  `event_timestamp` DATETIME NOT NULL COMMENT 'When it happened. Units: local time.',
  `entity_type` VARCHAR(40) NOT NULL COMMENT 'Table of the entity changed.',
  `entity_id` VARCHAR(60) NOT NULL COMMENT 'PK of the entity changed.',
  `event_type` VARCHAR(40) NOT NULL COMMENT 'What happened.',
  `actor_id` VARCHAR(40) NULL COMMENT 'Employee who acted (null for SYSTEM).',
  `actor_role` VARCHAR(40) NOT NULL COMMENT 'Capacity the actor acted in.',
  `from_state` VARCHAR(40) NULL COMMENT 'State before.',
  `to_state` VARCHAR(40) NULL COMMENT 'State after.',
  `related_case_id` VARCHAR(60) NULL COMMENT 'Onboarding/offboarding case context.',
  `reason` VARCHAR(200) NULL COMMENT 'Free-text justification.',
  PRIMARY KEY (`event_id`),
  KEY `ix_audit_event_entity_type_entity_id` (`entity_type`, `entity_id`),
  KEY `ix_audit_event_event_type` (`event_type`),
  KEY `ix_audit_event_event_timestamp` (`event_timestamp`),
  CONSTRAINT `fk_audit_event_actor_id` FOREIGN KEY (`actor_id`) REFERENCES `employee` (`employee_id`),
  CONSTRAINT `ck_audit_event_entity_type` CHECK (`entity_type` IN ('employee', 'onboarding_case', 'task', 'access_grant', 'asset', 'asset_assignment', 'offboarding_case')),
  CONSTRAINT `ck_audit_event_event_type` CHECK (`event_type` IN ('EMPLOYEE_HIRED', 'EMPLOYEE_STARTED', 'EMPLOYEE_TERMINATED', 'OFFER_WITHDRAWN', 'ROLE_CHANGED', 'START_DATE_CHANGED', 'CASE_CREATED', 'CASE_COMPLETED', 'CASE_CANCELLED', 'TASK_STARTED', 'TASK_COMPLETED', 'TASK_CANCELLED', 'GRANT_REQUESTED', 'GRANT_APPROVED', 'GRANT_REJECTED', 'GRANT_PROVISIONED', 'GRANT_REVOKED', 'GRANT_CANCELLED', 'ACCESS_OVERRIDE_APPROVED', 'ASSET_PURCHASED', 'ASSET_ASSIGNED', 'ASSET_DELIVERED', 'ASSET_ACKNOWLEDGED', 'ASSET_RETURNED', 'ASSET_LOST', 'ASSET_RETIRED')),
  CONSTRAINT `ck_audit_event_actor_role` CHECK (`actor_role` IN ('EMPLOYEE', 'MANAGER', 'HR_PARTNER', 'IT_OPS_PARTNER', 'SYSTEM_ADMIN', 'SYSTEM'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Append-only history of every state change, decision, exception and override.';
